// Simulating Private State & High-Performance Memoization via Closures
function createMemoizedCounter() {
  let count = 0; // Private lexical state
  const cache = new Map();

  return {
    increment() { return ++count; },
    getCount() { return count; },
    computeExpensive(n) {
      if (cache.has(n)) return cache.get(n);
      const result = n * count;
      cache.set(n, result);
      return result;
    }
  };
}

const counter = createMemoizedCounter();
console.log(counter.increment()); // 1
console.log(counter.computeExpensive(5)); // 5 (cached)

// Temporal Dead Zone (TDZ) and Execution Context Phases
console.log(typeof undeclaredVar); // "undefined" (not TDZ)

try {
  console.log(typeof declaredWithLet); // ReferenceError: Cannot access before initialization
  let declaredWithLet = 42;
