// Execution Order: Synchronous -> Microtasks -> Macrotasks
console.log("1 - Sync");

setTimeout(() => {
  console.log("2 - Macrotask (Timer)");
}, 0);

Promise.resolve().then(() => {
  console.log("3 - Microtask (Promise 1)");
}).then(() => {
  console.log("4 - Microtask (Promise 2)");
});

queueMicrotask(() => {
  console.log("5 - Microtask (queueMicrotask)");
});

console.log("6 - Sync");

// Output: 1 -> 6 -> 3 -> 5 -> 4 -> 2

// High-Performance Event Delegation with Target Matching
const table = document.querySelector("#settlements-table");

table.addEventListener("click", (event) => {
  const target = event.target;
  const button = target.closest("button[data-action]");
  if (!button || !table.contains(button)) return;

  const action = button.dataset.action;
  const rowId = button.closest("tr")?.dataset.rowId;
  console.log("Action:", action, "Row ID:", rowId);
});

// Production Debounce Utility with Immediate Execution and Cancel
function debounce(func, wait = 300, immediate = false) {
  let timeoutId = null;

  function debounced(...args) {
    const callNow = immediate && !timeoutId;
    clearTimeout(timeoutId);

    timeoutId = setTimeout(() => {
      timeoutId = null;
      if (!immediate) func.apply(this, args);
    }, wait);

    if (callNow) func.apply(this, args);
  }

  debounced.cancel = () => {
    clearTimeout(timeoutId);
    timeoutId = null;
  };

  return debounced;
}
